    var c = UI.tables[tn];
    if (c && c.codeInLabel && gr.getValue('code')) { n = gr.getValue('code') + ' · ' + n; }
    if (forOption && tn === 'lookup_value') { n = n + ' (' + gr.getValue('code') + ')'; }
    return n;
  }
  var refCache = {};
