  function choiceLabel(f, v) { if (!f.choices) { return v; } for (var i = 0; i < f.choices.length; i++) { if (f.choices[i][0] === v) { return lang === 'ar' ? (f.choices[i][2] || f.choices[i][1]) : f.choices[i][1]; } } return v; }

  // options for a reference field (form selects and filters)
  function refOptions(tb, f) {
    var g = new GlideRecordSecure(full(f.reference)), lk = UI.lookups && UI.lookups[tb.name + '.' + f.name];
    if (lk) { g.addQuery('type.code', lk); }
