    var ga = new GlideAggregate(full(t.name)); ga.addEncodedQuery(gr.getEncodedQuery()); ga.addAggregate('COUNT'); ga.query();
    var total = ga.next() ? parseInt(ga.getAggregate('COUNT'), 10) : 0;
