  function validate(vals, id) {
    var errors = {};
    t.fields.forEach(function (f) {
      if (f.name === 'legacy_id') { return; }
      var v = vals[f.name];
      if (f.type === 'boolean') { return; }
      v = str(v).replace(/^\s+|\s+$/g, '');
      if (f.mandatory && v === '') { errors[f.name] = msg('This field is required', 'هذا الحقل إلزامي'); return; }
      if (v === '') { return; }
      if (f.type === 'string' && f.length && v.length > f.length) { errors[f.name] = msg('At most ' + f.length + ' characters', 'الحد الأقصى ' + f.length + ' حرفاً'); return; }
      if (f.type === 'integer' && !/^-?[0-9]+$/.test(v)) { errors[f.name] = msg('Enter a whole number', 'أدخل رقماً صحيحاً'); return; }
