      if (f.choices) { var ok = false; for (var i = 0; i < f.choices.length; i++) { if (f.choices[i][0] === v) { ok = true; } } if (!ok) { errors[f.name] = msg('Choose a value from the list', 'اختر قيمة من القائمة'); return; } }
      if (f.type === 'reference') { var rg = new GlideRecordSecure(full(f.reference)); if (!rg.get(v)) { errors[f.name] = msg('Choose a value from the list', 'اختر قيمة من القائمة'); return; } }
      if (f.unique) { var ug = new GlideRecord(full(t.name)); ug.addQuery(f.name, v); if (id) { ug.addQuery('sys_id', '!=', id); } ug.setLimit(1); ug.query(); if (ug.hasNext()) { errors[f.name] = msg('This value is already used', 'هذه القيمة مستخدمة من قبل'); } }
    });
