  function doSave(inp) {
    var vals = inp.values || {}, id = str(inp.id), gr = new GlideRecordSecure(full(t.name));
    if (id) { if (!gr.get(id)) { return { ok: false, error: msg('Record not found', 'السجل غير موجود') }; } if (!gr.canWrite()) { return { ok: false, error: msg('You are not allowed to change this record', 'ليست لديك صلاحية تعديل هذا السجل') }; } }
    else { gr.initialize(); if (!gr.canCreate()) { return { ok: false, error: msg('You are not allowed to create records here', 'ليست لديك صلاحية الإضافة هنا') }; } }
    var errors = validate(vals, id);
    if (Object.keys(errors).length) { return { ok: false, errors: errors }; }
    t.fields.forEach(function (f) {
      if (f.name === 'legacy_id' || vals[f.name] === undefined) { return; }
      if (f.type === 'boolean') { gr.setValue(f.name, isTrue(vals[f.name]) ? 'true' : 'false'); }
      else { gr.setValue(f.name, str(vals[f.name]).replace(/^\s+|\s+$/g, '')); }
