    if (!gr.canDelete()) { return { ok: false, error: msg('You are not allowed to delete this record', 'ليست لديك صلاحية حذف هذا السجل') }; }
    var used = [];
    MODEL.tables.forEach(function (ot) { ot.fields.forEach(function (f) { if (f.type === 'reference' && f.reference === t.name) { var ag = new GlideAggregate(full(ot.name)); ag.addQuery(f.name, id); ag.addAggregate('COUNT'); ag.query(); var n = ag.next() ? parseInt(ag.getAggregate('COUNT'), 10) : 0; if (n > 0) { used.push(n + ' ' + lab(UI.tables[ot.name] ? UI.tables[ot.name].title : ot.plural)); } } }); });
    if (used.length) { return { ok: false, error: msg('It is used by ', 'مستخدم في ') + used.join(', ') }; }
    gr.deleteRecord();
